        if (typeof deferred.delayMs === "number") {
          job.state.nextRunAtMs = baseNow + deferred.delayMs + offset - staggerMs;
          offset += staggerMs;
          continue;
        }
        job.state.nextRunAtMs = baseNow + offset;
        offset += staggerMs;
      }
